66:       _filteredCurrenciesNotifier.value = _allCurrencies;
67:     } else {
68:       final String lowerQuery = query.toLowerCase();
69:       _filteredCurrenciesNotifier.value = _allCurrencies.where((currency) => currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery)).toList(growable: false);
70:     }
